int main(void) {
    int choice;
    printf("1 Play  2 Scores  3 Quit: ");
    scanf("%d", &choice);

    switch (choice) {
        case 1:
            printf("Starting...\n");
            break;
        case 2:
            printf("High scores\n");
            break;
        case 3:
            printf("Bye\n");
            break;
        default:
            printf("Not an option\n");
    }
    return 0;
}

